/* One local registry backs the area matrix and each job's profile. */
(()=>{
'use strict';
const KEY='cicluz-job-profiles-v1',LIMIT=240;
const groups=[['education','Formação'],['experience','Experiência'],['certificates','Certificações'],['technical','Competências técnicas'],['behavior','Competências comportamentais'],['individual','Entregas individuais'],['group','Entregas em grupo'],['collective','Entregas coletivas']];
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const button=(text,fn,cls='btn secondary')=>{const b=el('button',cls,text);b.type='button';b.onclick=fn;return b};
const fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
let data={areas:[],roles:[],requirements:[]},loadError=false,areaId='',query='';
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){if(!['areas','roles','requirements'].every(k=>Array.isArray(saved[k])))throw Error('format');data=saved}}catch{loadError=true}
const id=()=>crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
function transact(change){const before=structuredClone(data);try{if(loadError)throw Error('read');change();localStorage.setItem(KEY,JSON.stringify(data));return true}catch{data=before;return false}}
function catalog(){return jobsCurrent().map(e=>({...e,sourceId:e.key.startsWith('ref:')?e.key:'custom:'+JSON.stringify([e.j.nome,e.j.cbo||'']),name:e.j.nomeReduzido||e.j.nome}))}
function currentJob(role){return catalog().find(e=>e.sourceId===role.sourceId)}
function areaOptions(){let roots=[];try{const saved=JSON.parse(localStorage.getItem('cicluz-location-tree-v1')||'[]');roots=Array.isArray(saved)?saved:saved.tree||[]}catch{}
return [...roots.map(n=>({id:'location:'+n.id,name:n.name})),...data.areas].filter((n,i,a)=>a.findIndex(x=>x.id===n.id)===i)}
function knownAreas(){const list=areaOptions();for(const r of data.roles)if(!list.some(a=>a.id===r.areaId))list.push({id:r.areaId,name:r.areaName+' (área preservada)'});return list}
const view=el('section','view');view.id='job-profiles-view';view.style.setProperty('--menu-accent','#7c3aed');const panel=el('div','panel');panel.style.setProperty('--panel-color','#7c3aed');panel.style.setProperty('--panel-text','#5520ad');const head=el('div','head'),badge=el('span','origin-icon');badge.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h16v18H4zM8 7h8M8 12h8M8 17h4"/></svg>';const heading=el('div'),title=el('h2',null,'Ficha de Cargos'),subtitle=el('p',null,'Configurações / Gestão de Pessoas / Ficha de Cargos');heading.append(title,subtitle);head.append(heading);const body=el('div','content profiles-content');panel.append(head,body);view.append(panel);document.querySelector('main').append(view);
let back=()=>openSection(sections[6][0],'Gestão de Pessoas','people-settings','#7c3aed');addShortcuts(view.id,()=>back());
const searchButton=button('',()=>{searchBox.hidden=!searchBox.hidden;if(searchBox.hidden){query='';search.value='';renderMatrix()}else search.focus()},'shortcut-circle');searchButton.title='Buscar exigência';searchButton.setAttribute('aria-label','Buscar exigência');searchButton.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';head.querySelector('.shortcut-actions').append(searchButton);
const controls=el('div','profiles-controls'),areaLabel=el('label',null,'Área'),areaSelect=el('select');areaSelect.setAttribute('aria-label','Área do quadro');areaLabel.append(areaSelect);const addArea=button('+ Nova área',()=>areaEditor()),addRole=button('+ Vincular cargo',()=>roleEditor()),addReq=button('+ Adicionar exigência',()=>requirementEditor());controls.append(areaLabel,addArea,addRole,addReq);
const searchBox=el('div','profiles-search');searchBox.hidden=true;const search=el('input');search.type='search';search.placeholder='Buscar exigência';search.setAttribute('aria-label','Buscar exigência na área');search.oninput=()=>{query=search.value;renderMatrix()};searchBox.append(search);
const status=el('p','profiles-note');status.setAttribute('role','status');const matrix=el('div','profiles-matrix');matrix.tabIndex=0;matrix.setAttribute('role','region');matrix.setAttribute('aria-label','Exigências por cargo; deslize para os lados');const content=el('div','profiles-detail');
function activate(){document.querySelectorAll('.view').forEach(x=>x.classList.remove('show'));view.classList.add('show');document.getElementById('crumb').textContent='Configurações / Gestão de Pessoas / Ficha de Cargos';document.getElementById('title').textContent='Ficha de Cargos'}
function showMatrix(){activate();title.textContent='Ficha de Cargos';subtitle.textContent='Configurações / Gestão de Pessoas / Quadro por área';back=()=>openSection(sections[6][0],'Gestão de Pessoas','people-settings','#7c3aed');searchButton.hidden=false;body.replaceChildren(controls,searchBox,status,matrix);refreshAreas();renderMatrix();normalizeHeaderActions(view)}
window.showJobProfiles=showMatrix;
function refreshAreas(){const areas=knownAreas();if(!areas.some(a=>a.id===areaId))areaId=areas[0]?.id||'';areaSelect.replaceChildren(new Option('Selecione a área',''));areas.forEach(a=>areaSelect.add(new Option(a.name,a.id)));areaSelect.value=areaId;addRole.disabled=addReq.disabled=!areaId||loadError;addArea.disabled=loadError}
areaSelect.onchange=()=>{areaId=areaSelect.value;query='';search.value='';refreshAreas();renderMatrix()};
function report(text){status.textContent=text}
function renderMatrix(){matrix.replaceChildren();report(loadError?'Não foi possível ler o quadro salvo. Os dados foram preservados; recarregue a página.':'✓ Exigido · — Não exigido. Alterações salvas neste navegador.');const roles=data.roles.filter(r=>r.areaId===areaId),reqs=data.requirements.filter(r=>r.areaId===areaId&&fold(r.text).includes(fold(query)));
if(!areaId){matrix.append(el('p','profiles-empty','Selecione uma área cadastrada ou crie uma área para começar.'));return}
if(!roles.length){matrix.append(el('p','profiles-empty','Vincule os cargos desta área para montar o quadro. Cada cargo vem do cadastro de Cargos.'));return}
const table=el('table','profiles-table'),caption=el('caption','profiles-sr','Exigências da área '+areaSelect.selectedOptions[0].text),thead=el('thead'),tr=el('tr'),first=el('th',null,'Competência ou exigência');first.scope='col';tr.append(first);
roles.forEach(r=>{const th=el('th');th.scope='col';const j=currentJob(r);th.append(button(j?.name||r.jobName,()=>showProfile(r),'profiles-job-link'));const small=el('small',null,j?.j.cbo?'CBO '+j.j.cbo:r.cbo?'CBO '+r.cbo:'CBO não informado');th.append(small);tr.append(th)});thead.append(tr);table.append(caption,thead);const tbody=el('tbody');
for(const [key,label] of groups){const items=reqs.filter(r=>r.group===key);if(!items.length)continue;const section=el('tr','profiles-group');const sh=el('th',null,label);sh.scope='row';section.append(sh);roles.forEach(()=>section.append(el('td')));tbody.append(section);
for(const req of items){const row=el('tr'),labelCell=el('th');labelCell.scope='row';labelCell.append(button(req.text,()=>requirementEditor(req),'profiles-requirement'));row.append(labelCell);for(const role of roles){const td=el('td'),check=el('input');check.type='checkbox';check.checked=role.required.includes(req.id);check.disabled=loadError;check.setAttribute('aria-label',req.text+' — '+(currentJob(role)?.name||role.jobName));check.onchange=()=>{const checked=check.checked;if(!transact(()=>{role.required=checked?[...new Set([...role.required,req.id])]:role.required.filter(x=>x!==req.id)})){renderMatrix();report('Não foi possível salvar. A marcação anterior foi mantida.')}else report('Salvo neste navegador.')};td.append(check);row.append(td)}tbody.append(row)}}
table.append(tbody);matrix.append(table);if(!reqs.length)matrix.append(el('p','profiles-empty',query?'Nenhuma exigência encontrada.':'Adicione as exigências da área e marque em quais cargos se aplicam.'))}
function dialog(titleText,build,onSave,after=showMatrix){const d=el('dialog','location-dialog profiles-dialog');d.style.setProperty('--menu-accent','#7c3aed');const h=el('h2',null,titleText),form=el('form','account-editor'),err=el('p','profiles-error');err.setAttribute('role','alert');const field=(name,node)=>{const l=el('label',null,name);node.setAttribute('aria-label',name);l.append(node);form.append(l);return node};const result=build(field,form);const actions=el('div','actions'),save=el('button','btn','Salvar');save.type='submit';actions.append(button('Cancelar',()=>d.close()),save);form.append(err,actions);form.onsubmit=e=>{e.preventDefault();const message=onSave(result);if(message){err.textContent=message;return}d.close();after()};d.append(h,form);document.body.append(d);d.onclose=()=>d.remove();d.showModal();form.querySelector('input,select,textarea')?.focus();return d}
function areaEditor(){dialog('Nova área',field=>{const name=field('Nome da área',el('input'));name.required=true;name.maxLength=100;return name},name=>{const text=name.value.trim();if(!text)return 'Informe o nome da área.';if(knownAreas().some(a=>fold(a.name)===fold(text)))return 'Esta área já está cadastrada.';const next={id:'profile:'+id(),name:text};return transact(()=>{data.areas.push(next);areaId=next.id})?null:'Não foi possível salvar a área.'})}
function roleEditor(existing){dialog(existing?'Editar ficha do cargo':'Vincular cargo à área',(field,form)=>{
const entries=catalog(),search=field('Buscar cargo por nome reduzido ou CBO',el('input'));search.type='search';const select=field('Cargo',el('select'));select.required=true;let selected=existing?.sourceId||'';function options(){selected=select.value||selected;select.replaceChildren(new Option('Selecione o cargo',''));entries.filter(e=>e.sourceId===selected||fold([e.name,e.j.nome,e.j.cbo].join(' ')).includes(fold(search.value))).forEach(e=>select.add(new Option(e.name+' · '+e.j.nome+(e.j.cbo?' · CBO '+e.j.cbo:''),e.sourceId)));select.value=selected}options();search.oninput=options;
const cbo=field('CBO do cadastro',el('input'));cbo.readOnly=true;function update(){selected=select.value;const entry=entries.find(e=>e.sourceId===selected);cbo.value=entry?.j.cbo||'';cbo.placeholder='Não informado no cadastro'}select.onchange=update;update();
const mission=field('Principal função do cargo',el('textarea'));mission.rows=2;mission.maxLength=LIMIT;mission.value=existing?.mission||'';const count=el('small','profiles-note');mission.parentElement.append(count);mission.oninput=()=>count.textContent=mission.value.length+'/'+LIMIT+' caracteres';mission.oninput();form.append(el('p','profiles-note','Limite inicial de 240 caracteres; pode ser revisto.'));
const autonomy=field('Autonomia — decisões e autorizações',el('textarea'));autonomy.rows=3;autonomy.value=existing?.autonomy||'';return {entries,select,mission,autonomy}},f=>{const entry=f.entries.find(e=>e.sourceId===f.select.value);if(!entry)return 'Selecione um cargo existente.';if(data.roles.some(r=>r.areaId===areaId&&r.sourceId===entry.sourceId&&r.id!==existing?.id))return 'Este cargo já está vinculado à área.';const fields={sourceId:entry.sourceId,jobName:entry.name,cbo:entry.j.cbo||'',mission:f.mission.value.trim(),autonomy:f.autonomy.value.trim()};return transact(()=>{if(existing)Object.assign(existing,fields);else data.roles.push({id:id(),areaId,areaName:areaSelect.selectedOptions[0].text,required:[],...fields})})?null:'Não foi possível salvar a ficha.'},existing?()=>showProfile(data.roles.find(r=>r.id===existing.id)):showMatrix)}
function requirementEditor(existing,initialGroup){dialog(existing?'Editar exigência':'Adicionar exigência',field=>{const category=field('Grupo',el('select'));groups.forEach(([k,v])=>category.add(new Option(v,k)));category.value=existing?.group||initialGroup||'technical';const text=field('Exigência ou entrega',el('textarea'));text.rows=3;text.required=true;text.value=existing?.text||'';return {category,text}},f=>{const text=f.text.value.trim();if(!text)return 'Descreva a exigência ou entrega.';if(data.requirements.some(r=>r.areaId===areaId&&r.group===f.category.value&&fold(r.text)===fold(text)&&r.id!==existing?.id))return 'Este item já existe neste grupo da área.';return transact(()=>{if(existing)Object.assign(existing,{text,group:f.category.value});else data.requirements.push({id:id(),areaId,group:f.category.value,text})})?null:'Não foi possível salvar a exigência.'})}
function showProfile(role){activate();const source=currentJob(role);title.textContent=source?.name||role.jobName;subtitle.textContent='Ficha de Cargos / '+(knownAreas().find(a=>a.id===role.areaId)?.name||role.areaName);back=showMatrix;searchButton.hidden=true;body.replaceChildren(content);content.replaceChildren();const toolbar=el('div','profiles-controls');toolbar.append(button('Voltar ao quadro',showMatrix),button('Editar identificação e função',()=>roleEditor(role),'btn'));content.append(toolbar);
const info=el('dl','profiles-info');for(const [label,text] of [['Cargo',source?.j.nome||role.jobName],['CBO',source?.j.cbo||role.cbo||'Não informado no cadastro'],['Principal função',role.mission||'Ainda não preenchida'],['Autonomia',role.autonomy||'Ainda não preenchida']])info.append(el('dt',null,label),el('dd',null,text));content.append(info);if(!source)content.append(el('p','profiles-note','O vínculo original foi preservado. Use Editar identificação e função para selecionar um cargo atual.'));
for(const [key,name] of groups){const block=el('section','profiles-section');block.append(el('h3',null,name));const requirements=data.requirements.filter(r=>r.areaId===role.areaId&&r.group===key);requirements.filter(r=>role.required.includes(r.id)).forEach(r=>block.append(el('p','profiles-delivery',r.text)));if(!requirements.some(r=>role.required.includes(r.id)))block.append(el('p','profiles-note','Nenhum item exigido neste grupo.'));block.append(button(key==='individual'||key==='group'||key==='collective'?'+ Adicionar entrega':'+ Selecionar exigências',()=>selectRequirements(role,key)));content.append(block)}normalizeHeaderActions(view)}
function selectRequirements(role,key){const name=groups.find(g=>g[0]===key)[1];dialog(name,(field,form)=>{const selected=new Set(role.required);const rows=data.requirements.filter(r=>r.areaId===role.areaId&&r.group===key);if(!rows.length)form.append(el('p','profiles-note','Nenhum item cadastrado neste grupo.'));rows.forEach(r=>{const label=el('label','profiles-choice'),check=el('input');check.type='checkbox';check.checked=selected.has(r.id);check.onchange=()=>check.checked?selected.add(r.id):selected.delete(r.id);label.append(check,el('span',null,r.text));form.append(label)});const text=field('Nova exigência ou entrega (opcional)',el('textarea'));text.rows=2;return {selected,text,rows}},f=>{const text=f.text.value.trim();return transact(()=>{role.required=[...f.selected];if(text){let req=data.requirements.find(r=>r.areaId===role.areaId&&r.group===key&&fold(r.text)===fold(text));if(!req){req={id:id(),areaId:role.areaId,group:key,text};data.requirements.push(req)}role.required=[...new Set([...role.required,req.id])]}})?null:'Não foi possível salvar os itens.'},()=>showProfile(data.roles.find(r=>r.id===role.id)))}
})();
